from lesson_authoring import entry as E
from author_batch200_root_bio_a import B,H
BT=B[:1]+[['希腊 biotikos → 拉丁 bioticus','与生命有关的'],['英语 biotic','生命的、生物的']]
WB=[
E('biomedical','英 /ˌbaɪəʊˈmedɪkəl/；美 /ˌbaɪoʊˈmedɪkəl/','生物医学的','把对细胞、器官和生命过程的认识，用来研究健康与疾病。','bio-“生物” + medical“医学的”，近代英语组合词。',H(B,'英语 bio- + medical → biomedical','生物与医学相关的'),'biomedical research 可能研究疾病机制，也可能研究检测或治疗技术。这个词只说明研究与生物医学相关，不意味着成果已经能用于患者，更不意味着已经证实有效。','biomedical research；biomedical science；biomedical engineering。','biomedical 说学科及研究方向；clinical 常说与患者、临床实践或试验相关。基础研究也可以是 biomedical。',('The institute supports biomedical research.','研究所支持生物医学研究。'),('She studied biomedical engineering at university.','她在大学学习生物医学工程。'),sources=['https://en.wiktionary.org/wiki/biomedical','https://www.merriam-webster.com/dictionary/biomedical']),
E('biomedicine','英 /ˌbaɪəʊˈmedɪsɪn/；美 /ˌbaɪoʊˈmedɪsən/','生物医学；以生物科学为基础的医学','先弄清身体怎样运转、哪里出了问题，再研究怎样检测和处理。','bio-“生物” + medicine“医学”，把生命科学与医学联系起来。',H(B,'英语 bio- + medicine → biomedicine','以生物科学理解健康与疾病的医学领域'),'biomedicine 可以指把生物学、生理学知识用于医学的研究和实践。一些文章也用它概括主流现代医学体系。它不是一颗叫“生物”的药，而是理解和处理健康问题的一类知识与方法。','advances in biomedicine；research in biomedicine；modern biomedicine。','biomedicine 是领域或医学体系；a biopharmaceutical 通常是一种具体生物药物。',('The discovery opened a new area of research in biomedicine.','这项发现为生物医学打开了新的研究方向。'),('The course links molecular biology with biomedicine.','课程把分子生物学与生物医学联系起来。'),sources=['https://en.wiktionary.org/wiki/biomedicine','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/biomedicine']),
E('biopsy','英 /ˈbaɪɒpsi/；美 /ˈbaɪɑːpsi/','活组织检查；取样活检','从活体取得一点细胞或组织，再仔细看里面发生了什么。','bi-“生命” + -opsy“观察”，经法语 biopsie 进入英语；这里 bi- 不是数字二。',B+[['近代法语 bi- + -opsie → biopsie','活体 + 观察 → 活组织检查'],['英语 biopsy；后来也作动词','活检；对某部位取样活检']],'biopsy 的关键是取得细胞或组织样本进行检查，可以用显微镜，也可以做其他分析。并不是所有活检都要切下一大块组织。它是检查过程或样本相关用语，不是某一种疾病的名字。','have a biopsy；a tissue biopsy；a biopsy sample。','biopsy 取样检查活体材料；autopsy 通常指死后尸检。两词的 -opsy 都与观察有关。',('The sample was sent to the laboratory after the biopsy.','活检后，样本被送到了实验室。'),('The doctor explained why a biopsy was needed.','医生解释了为什么需要活检。'),sources=['https://www.etymonline.com/word/biopsy','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/biopsy']),
E('antibiotic','英 /ˌæntibaɪˈɒtɪk/；美 /ˌæntibaɪˈɑːtɪk/，anti- 也可读 /ˌæntaɪ-/','抗生素；抗生的','针对细菌的某些生存环节下手，让它们难以生长或存活。','anti-“对抗” + biotic“与生命有关的”，英语与法语 antibiotique 相接；医学中的实际意义比字面更具体。',B[:1]+[['希腊 biotikos → 后期拉丁 bioticus → 法语 biotique','与生命有关的'],['法语 anti- + biotique → antibiotique → 英语 antibiotic 形容词','抑制、破坏微生物生命活动的'],['英语 antibiotic 名词','抗生素']],'日常医疗中的 antibiotic 通常指用于对付细菌的药物，不是万能的“杀病原体药”。它不能治疗病毒引起的感冒或流感。词根能解释命名的方向，但不能仅凭 anti + bio 推出作用对象和用途。','an antibiotic；antibiotic treatment；antibiotic resistance。','antibiotic 常针对细菌；antiviral 针对病毒。anti- 相同，后面的作用对象不同。',('The infection did not respond to that antibiotic.','这种感染对那种抗生素没有反应。'),('Antibiotics do not treat the viruses that cause colds.','抗生素不能治疗引起感冒的病毒。'),sources=['https://www.etymonline.com/word/antibiotic','https://www.cdc.gov/antibiotic-use/communication-resources/virus-or-bacteria.html']),
E('probiotic','英 /ˌprəʊbaɪˈɒtɪk/；美 /ˌproʊbaɪˈɑːtɪk/','益生微生物；益生菌制剂；益生的','这里不是把微生物赶走，而是利用特定活微生物带来的健康益处。','pro-“有利于、支持” + biotic“生命相关的”，属于近代构词，含义随研究发展而明确。',BT+[['近代 pro- + biotic → probiotic','有利于生命的 → 特定益生微生物及相关制品']],'科学用法中的 probiotics 是在足够数量下能给宿主带来健康益处的活微生物，既可能是细菌，也可能是酵母。不是所有活菌、发酵食品都自动算 probiotic；效果也不能从一种菌株直接推广到所有产品。','a probiotic strain；a probiotic product；probiotic bacteria。','probiotic 是起作用的活微生物；prebiotic 通常是被某些微生物利用、并产生健康益处的物质。',('The study tested one specific probiotic strain.','这项研究测试了一种特定的益生菌株。'),('The label lists the probiotic strains in the product.','标签列出了产品中的益生微生物菌株。'),sources=['https://en.wiktionary.org/wiki/probiotic','https://ods.od.nih.gov/factsheets/Probiotics-HealthProfessional/']),
E('prebiotic','英 /ˌpriːbaɪˈɒtɪk/；美 /ˌpriːbaɪˈɑːtɪk/','生命出现前的；益生元；益生元的','一个语境是在问生命出现前的化学；另一个是在说喂养特定微生物的材料。','pre-“在前” + biotic；营养学中的专门意义后来发展，不能用同一条中文释义套所有语境。',BT+[['英语 pre- + biotic → prebiotic','生命出现前的'],['后来营养与微生物研究中的 prebiotic','被宿主微生物选择性利用并带来健康益处的物质']],'prebiotic chemistry 研究生命起源前的化学过程；a prebiotic ingredient 则说益生元成分。后者可先想成微生物能利用的“食物”，但正式定义还要求选择性利用和宿主获益，因此不等于所有膳食纤维。','prebiotic chemistry；a prebiotic ingredient；prebiotic fiber。','probiotic 是活微生物；prebiotic 是它们或其他宿主微生物可利用的某些物质。两个词在营养语境中常一起出现，但不是同一种东西。',('The laboratory studies prebiotic chemistry.','实验室研究生命起源前的化学过程。'),('The researchers tested whether the ingredient had a prebiotic effect.','研究者测试了这种成分是否具有益生元作用。'),sources=['https://www.merriam-webster.com/dictionary/prebiotic','https://isappscience.org/topic/prebiotics/','https://www.nature.com/articles/nrgastro.2017.75']),
E('bioavailability','英 /ˌbaɪəʊəˌveɪləˈbɪləti/；美 /ˌbaɪoʊəˌveɪləˈbɪləti/','生物利用度','吃进去了多少，不等于身体真正能用上多少；还要看它怎样到达作用位置。','bio-“生物体” + availability“可利用性”，是把“能够取得、使用”具体化到生物体内。',H(B,'英语 bio- + availability → bioavailability','生物体内的可利用程度'),'药物语境中 bioavailability 关注活性成分从制剂中被吸收、到达作用部位的速度和程度。口服后的一些成分可能没有被吸收，或在到达前已被处理掉。因此它不同于包装上写的含量，也不直接等于药效强弱。','oral bioavailability；low bioavailability；improve bioavailability。','dose 是给了多少；bioavailability 是给进去以后有多少、以多快速度能到达相关位置供作用。',('The two formulations have different oral bioavailability.','这两种制剂的口服生物利用度不同。'),('The study measured the compound’s bioavailability.','研究测量了这种化合物的生物利用度。'),sources=['https://en.wiktionary.org/wiki/bioavailability','https://www.fda.gov/media/166003/download']),
E('bioactive','英 /ˌbaɪəʊˈæktɪv/；美 /ˌbaɪoʊˈæktɪv/','有生物活性的；能影响生物过程的','它不是只待在那里，而是会让生物系统发生某种反应。','bio-“生物” + active“有活性的、起作用的”。',H(B,'英语 bio- + active → bioactive','在生物系统中能产生作用的'),'bioactive compound 可以影响细胞、酶或其他生物过程。这个词只说“能起生物作用”，没有保证作用一定有益，也没有说明需要多少、在什么条件下起作用。读产品宣传时尤其不要把它直接译成“有益健康”。','a bioactive compound；bioactive molecules；bioactive substances。','bioactive 说有生物作用；biocompatible 说在特定用途下与生物组织相容。能起作用与适合接触人体是两种判断。',('The extract contains several bioactive compounds.','这种提取物含有几种具有生物活性的化合物。'),('The researchers tested whether the molecule was bioactive.','研究者测试了这个分子是否具有生物活性。'),sources=['https://en.wiktionary.org/wiki/bioactive','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/bioactive-compound']),
E('biotin','/ˈbaɪətɪn/','生物素，一种B族维生素','它像某些酶工作时需要配上的小零件，参与身体处理营养物质。','经德语 Biotin，接希腊 biotos“生命”与化学物质后缀 -in。',B[:1]+[['希腊 biotos“生命” + -in → 德语 Biotin','以生命词族命名的物质'],['英语 biotin','生物素，B族维生素之一']],'biotin 帮助某些酶发挥作用，参与碳水化合物、脂肪和蛋白质等的代谢。它是具体的一种营养素，不是“所有生物营养”的统称。词名中的 bio- 也不能证明额外补充就一定有额外好处。','dietary biotin；biotin deficiency；foods containing biotin。','biotin 是生物素；biosynthesis 是生物合成。两词都带 bio-，一个是物质，一个是过程。',('Biotin is found in a variety of foods.','多种食物中都含有生物素。'),('The chapter explains biotin’s role in enzyme activity.','这一章解释了生物素在酶活动中的作用。'),sources=['https://en.wiktionary.org/wiki/biotin','https://ods.od.nih.gov/factsheets/biotin-consumer/']),
E('biopharmaceutical','英 /ˌbaɪəʊˌfɑːməˈsuːtɪkəl/；美 /ˌbaɪoʊˌfɑːrməˈsuːtɪkəl/','生物药物；生物制药的','让生物材料或生物技术参与生产药物。','bio- + pharmaceutical“药物、制药的”，现代技术词汇。',H(B,'英语 bio- + pharmaceutical → biopharmaceutical','生物来源或通过生物技术生产的药物；相关的'),'a biopharmaceutical 常指生物来源、尤其利用生物技术生产的药物，例如某些治疗性蛋白质。作形容词时可说 biopharmaceutical research“生物制药研究”。它不是一切从植物里找到的日用品，也不自动表示更安全。','a biopharmaceutical company；biopharmaceutical research；develop a biopharmaceutical。','pharmaceutical 泛指药物或制药的；biopharmaceutical 特别指出生物来源、技术或相应产业。',('The company develops biopharmaceuticals for several diseases.','公司为几种疾病开发生物药物。'),('She works in biopharmaceutical manufacturing.','她从事生物药物制造工作。'),sources=['https://www.merriam-webster.com/dictionary/biopharmaceutical','https://en.wiktionary.org/wiki/biopharmaceutical']),
E('biomarker','英 /ˈbaɪəʊˌmɑːkə/；美 /ˈbaɪoʊˌmɑːrkər/','生物标志物；反映生物状态的可测指标','身体里的变化不一定能直接看到，但可以通过某个可测的信号留下线索。','bio-“生物” + marker“标记、指标”，把生物过程与可观测线索联系起来。',H(B,'英语 bio- + marker → biomarker','标记生物状态或过程的指标'),'某种分子的水平可以用作 biomarker，帮助研究正常过程、疾病变化或治疗反应。它给出的是线索，是否能用于某项判断需要验证；不能把一个指标升高直接等同于某种疾病已经确诊。','a biomarker for；a potential biomarker；measure a biomarker。','symptom 是人感受到或报告的不适等症状；biomarker 是可以客观测量、用来反映状态的指标。',('The protein is being studied as a possible biomarker.','研究者正在考察这种蛋白质能否用作生物标志物。'),('The team measured changes in the biomarker over time.','团队测量了这一生物标志物随时间的变化。'),sources=['https://en.wiktionary.org/wiki/biomarker','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/biomarker']),
]
